const cat = JSON.parse($('Config').first().json.shop_catalog);
const points = Number($input.first().json.points || 0);
let text = '🌟 امتیاز تو: ' + points + '\n\n';
cat.forEach(i => { text += i.id + '. ' + i.title + ' — ' + i.cost + ' امتیاز\n'; });
text += '\nشماره‌ی جایزه‌ای که می‌خوای رو انتخاب کن:';
return [{ json: { text } }];

const cat = JSON.parse($('Config').first().json.shop_catalog);
const t = $('Telegram Trigger').first().json;
const id = Number(t.callback_query.data.replace('buy_', ''));
const item = cat.find(i => i.id === id);
const u = $input.first().json;
const points = Number(u.points || 0);
if (!u.telegram_id) return [{ json: { ok: false, text: 'ابتدا /start رو بزن.' } }];
if (!item) return [{ json: { ok: false, text: 'این گزینه دیگه موجود نیست.' } }];
if (points < item.cost) return [{ json: { ok: false, text: '❌ امتیاز کافی نیست.\nامتیاز تو: ' + points + '\nقیمت: ' + item.cost } }];
const left = points - item.cost;
return [{ json: { ok: true, new_points: left, item: item.title, cost: item.cost,
  text: '✅ «' + item.title + '» ثبت شد.\n' + item.cost + ' امتیاز کم شد؛ امتیاز باقی‌مانده: ' + left + '\nبه‌زودی پشتیبانی باهات تماس می‌گیره.' } }];

const m = $('Telegram Trigger').first().json.message;
const match = (m.reply_to_message.text || '').match(/ID:\s*(\d+)/);
if (!match || !m.text) return [];
return [{ json: { user_id: match[1], reply: m.text } }];

const rows = $input.all().map(i => i.json).filter(r => r.name && String(r.active ?? 'TRUE').toUpperCase() !== 'FALSE');
let text = '';
if (!rows.length) {
  text += '\nهنوز ابزاری ثبت نشده؛ به‌زودی پر می‌شه 🙌';
  return [{ json: { text } }];
}
const groups = {};
rows.forEach(r => { (groups[r.category || 'متفرقه'] = groups[r.category || 'متفرقه'] || []).push(r); });
let shown = 0;
outer: for (const cat of Object.keys(groups)) {
  let block = '\n📂 ' + cat + '\n';
  for (const r of groups[cat]) {
    const line = '• ' + r.name + (r.description ? ' — ' + r.description : '') + (r.url ? '\n  ' + r.url : '') + '\n';
    if ((text + block + line).length > 3800) { text += block + '\n… و ابزارهای بیشتر به‌زودی'; break outer; }
    block += line; shown++;
  }
  text += block;
}
return [{ json: { text } }];
